function Tooltip({ text }) {
  const ref = useRef(null);
  const [h, setH] = useState(0);

  useLayoutEffect(() => {
    setH(ref.current.offsetHeight);
  }, [text]);

  return <div ref={ref} style={{ top: -h }}>{text}</div>;
}

