function Stopwatch() {
  const id = useRef(null);

  function start() {
    id.current = setInterval(tick, 1000);
  }

  function stop() {
    clearInterval(id.current);
  }
}

function usePrevious(value) {
  const ref = useRef();

  useEffect(() => {
    ref.current = value;
  });

  return ref.current;
}

function Counter() {
  const [n, setN] = useState(0);
  const prev = usePrevious(n);

  return <p>Agora: {n}, antes: {prev}</p>;
}

function Chart({ data }) {
  const el = useRef(null);
  const chart = useRef(null);

  useEffect(() => {
    chart.current ??= new ChartLib(el.current);
    chart.current.update(data);
  }, [data]);

  return <canvas ref={el} />;
}

function Field({ ref }) {
  const inner = useRef(null);

  useImperativeHandle(ref, () => ({
    focus() {
      inner.current.focus();
    },
  }));

  return <input ref={inner} />;
}

function Form() {
  const ref = useRef(null);

  return (
    <>
      <Field ref={ref} />
      <button onClick={() => ref.current.focus()}>
        Focar
      </button>
    </>
  );
}

